#ifdef ESP32
  #define LED_PIN 2       // ESP32 Dev Module built-in LED
#else
  #define LED_PIN 13      // Arduino Uno built-in LED
#endif

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  delay(1000);

  digitalWrite(LED_PIN, LOW);
  delay(1000);
}
